SELECT QUARTER(customers.signup_date) AS signup_quarter, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(orders.status))) AS status_values, SUM(orders.amount) AS total_amount FROM orders INNER JOIN stores ON orders.store_id = stores.id LEFT JOIN customers ON customers.id = orders.customer_id WHERE orders.channel IN ('partner', 'mobile') GROUP BY QUARTER(customers.signup_date) HAVING total_amount >= 5300 ORDER BY signup_quarter
